      lazyPlot("#h_hotm", () => plot("#h_hotm", [{ type: "bar", x: MONTHS, y: ev.hot_by_month.map((r) => +r.hot.toFixed(1)), name: "Hot", marker: { color: "#f08c00" } }, { type: "bar", x: MONTHS, y: ev.hot_by_month.map((r) => +r.danger.toFixed(1)), name: "Dangerous", marker: { color: "#c92a2a" } }], { barmode: "stack", height: 320, showlegend: false, yaxis: { title: "days per month, average year" } }, "Hot days by month."));
