        $("#t_otd").textContent = `On ${now.toLocaleDateString("en-IN", { day: "numeric", month: "long" })} the afternoon high has ranged from ${range(tmx)[0]} to ${range(tmx)[1]} °C (average ${avg.toFixed(1)} °C)`;
